from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 5))
    k = draw(st.integers(1, n))
    m = draw(st.integers(1, 4))
    lines = [f"{n} {m} {k}"]
    for _ in range(m):
        keys = draw(st.lists(st.integers(1, n), min_size=1, max_size=n, unique=True))
        r = draw(st.sampled_from(["o", "x"]))
        lines.append(" ".join([str(len(keys))] + [str(x) for x in keys] + [r]))
    return "\n".join(lines) + "\n"


def _parse(inp):
    lines = inp.strip().split("\n")
    n, m, k = map(int, lines[0].split())
    if len(lines) != m + 1:
        raise ValueError("line count")
    tests = []
    for i in range(m):
        t = lines[1 + i].split()
        c = int(t[0])
        if len(t) != c + 2:
            raise ValueError("token count")
        a = [int(x) for x in t[1:1 + c]]
        r = t[1 + c]
        tests.append((a, r))
    return n, m, k, tests


def validate(inp):
    try:
        n, m, k, tests = _parse(inp)
    except Exception:
        return False
    if not (1 <= k <= n <= 15):
        return False
    if not (1 <= m <= 100):
        return False
    for a, r in tests:
        c = len(a)
        if not (1 <= c <= n):
            return False
        if len(set(a)) != c:
            return False
        if any(not (1 <= x <= n) for x in a):
            return False
        if r not in ("o", "x"):
            return False
    return True


def ref(inp):
    n, m, k, tests = _parse(inp)
    tmasks = []
    for a, r in tests:
        tm = 0
        for x in a:
            tm |= 1 << (x - 1)
        tmasks.append((tm, r))
    count = 0
    for mask in range(1 << n):
        ok = True
        for tm, r in tmasks:
            cnt = bin(mask & tm).count("1")
            opened = cnt >= k
            if opened != (r == "o"):
                ok = False
                break
        if ok:
            count += 1
    return str(count)
